int main() {
  int n, m; cin >> n >> m;
  vector<string> a(n), b(m);
  REP(i, n) cin >> a[i];
  REP(i, m) cin >> b[i];
  bool yes = false;
  REP(i, n - m + 1) {
    int l = (int)a[i].find(b[0]);
    if (l > -1) {
      yes = true;
      REP(j, m) {
        if (a[i + j].substr(l, m) != b[j]) yes = false;
      }
    }
    if (yes == true) break;
  }
  cout << (yes ? "Yes" : "No") << endl;
  return 0;
