int dfs(int x,int pre)
{
	if(v[x].size()==1 && pre!=-1) 
	{
		c[x]=1;
		return 1;
	}
	int ret=1;
	for(int i=0;i<v[x].size();i++) if(v[x][i]!=pre) ret+=dfs(v[x][i],x);
	c[x]=ret;
	return ret;
}

void dfs2(int x,int d,int pre)
{
	dep[x]=d;
	for(int i=0;i<v[x].size();i++) if(v[x][i]!=pre) dfs2(v[x][i],d+1,x);
}

