int num[200000];

void num2bin(const int _num, int _binary[20]) {
	int dammy = _num;
	REP(i, 20) {
		_binary[i] = dammy % 2;
		dammy /= 2;
	}
}

bool update_sum(ll &_sum, const int _num) {
	int sum_bin[20], num_bin[20];
	num2bin(_sum, sum_bin);
	num2bin(_num, num_bin);
	REP(i, 20) {
		if (sum_bin[i] == 1 && num_bin[i] == 1) return false;
	}
	_sum += _num;
	return true;
}

