	int N;
	cin >> N;
	REP(i, N) {
		cin >> num[i];
	}

	ll ans = 0;
	ll sum = 0;

	// しゃく取り法
	// Start
	REP(i, N) {

		if (i > 0) {
			sum -= num[i - 1];
			right_ix[i] = right_ix[i - 1];

			// End
			REPS(j, right_ix[i - 1] + 1, N) {
				if (update_sum(sum, num[j])) {
					right_ix[i] = j;
				}
				else {
					right_ix[i] = j - 1;
					break;
				}
			}
		}
		// i==0 のとき
		else {
			REP(j, N) {
				if (update_sum(sum, num[j])) {
					right_ix[0] = j;
				}
				else {
					right_ix[0] = j - 1;
					break;
				}
			}
		}
