class CMP
{public:
bool operator()(ii a , ii b) //For min priority_queue .
{    return ! ( a.X < b.X || a.X==b.X && a.Y <= b.Y);   }};

void add( map<lli,lli> &m, lli x,lli cnt=1)
{
    auto jt=m.find(x);
    if(jt==m.end())         m.insert({x,cnt});
    else                    jt->Y+=cnt;
}

void del( map<lli,lli> &m, lli x,lli cnt=1)
{
    auto jt=m.find(x);
    if(jt->Y<=cnt)            m.erase(jt);
    else                      jt->Y-=cnt;
}

bool cmp(const ii &a,const ii &b)
{
    return a.X<b.X||(a.X==b.X&&a.Y<b.Y);
}

const lli mod = 1000000007L;
const lli maxN = 2*100000L;
const lli logN = 20;

    lli T,n,i,j,k,in,cnt,l,r,u,v,x,y;
    lli m,q,c,w;
    string s;
    vector<pair<lli,ii>> e[maxN+5];
    lli h[maxN+5],p[logN+5][maxN+5];
    lli tin[maxN+5],tout[maxN+5];
    map<lli,lli> flen[4*maxN+5],fcnt[4*maxN+5];
    vii elr;
    //priority_queue < ii , vector < ii > , CMP > pq;// min priority_queue .

bool isAnc(lli l,lli u)
{
    return tin[l]<=tin[u]&&tout[u]<=tout[l];
}

lli lca(lli u,lli v)
{
    if(isAnc(v,u))
        return v;
    swap(u,v);
    if(isAnc(v,u))
        return v;
    lli i;
    repD(i,logN,0)
        if(!isAnc(p[i][u],v))
            u=p[i][u];
    u=p[0][u];
    return u;
}

void dfs(lli u,lli pa,lli s)
{
    h[u]=s;
    p[0][u]=pa;
    tin[u]=++T;
    lli i;
    repA(i,1,logN)
        p[i][u]=p[i-1][p[i-1][u]];

    for(auto x:e[u])
    {
        if(x.X==pa)
            continue;
        elr.pb(x.Y);
        dfs(x.X,u,s+x.Y.Y);
        elr.pb({x.Y.X,-x.Y.Y});
    }
    tout[u]=++T;
}

ii query(lli id,lli l,lli r,lli L,lli R,lli c)
{
    if(R<l||r<L)
        return {0,0};
    if(L<=l&&r<=R)
    {
        ii ans={0,0};
        ans={flen[id][c],fcnt[id][c]};
        return ans;
    }
    lli m=(l+r)/2;
    ii a,b;
    a=query(2*id,l,m,L,R,c);
    b=query(2*id+1,m+1,r,L,R,c);
    return {a.X+b.X,a.Y+b.Y};
}

lli solve(lli l,lli u,lli c,lli len)
{
    if(l==u)
        return 0;
    lli ans=h[u]-h[l];
    ii x=query(1,1,T,tin[l],tin[u]-1,c);//sum,cnt;
    dbg(x,l,u,c);
    ans-=x.X;
    ans+=len*x.Y;
    return ans;
}

void build(lli id,lli l,lli r)
{
    lli i;
    repA(i,l,r)
    {
        flen[id][elr[i].X]+=elr[i].Y;
        fcnt[id][elr[i].X]+=elr[i].Y/abs(elr[i].Y);
    }
    if(l==r)
        return;
    lli m=(l+r)/2;
    build(2*id,l,m);
    build(2*id+1,m+1,r);
}

