    {
        cin>>u>>v>>c>>w;
        e[u].pb({v,{c,w}});
        e[v].pb({u,{c,w}});
    }

    dfs(1,1,0);
    T-=2;
    dbg(T,(lli)elr.size());
    build(1,1,T);
    dbg(elr);
    dbg(tin[1],tin[4],tin[5]);
    while(q--)
    {
        cin>>x>>y>>u>>v;
        l=lca(u,v);
        cout<<solve(l,u,x,y)+solve(l,v,x,y)<<endl;
