#include <bits/stdc++.h>
using namespace std;

int main()
{
  int N, M;
  cin >> N >> M;

  // 座標
  vector<int> coordinates(M);
  for(int i = 0; i < M; ++i)
  {
    cin >> coordinates.at(i);
  }

  // 座標小さい順にソート
  sort(coordinates.begin(), coordinates.end());

  // 座標同士の間隔（一番小さい座標から順番）
  vector<int> intervals(M - 1);
  for(int i = 0; i < M - 1; ++i)
  {
    intervals.at(i) = coordinates.at(i + 1) - coordinates.at(i);
  }

  sort(intervals.begin(), intervals.end(), greater<type>());

  // 差っ引く間隔の合計
  long deletedintervals = 0;
  // 座標が全てコマで埋まるなら差っ引く必要無し
  if(M > N)
  {
    for(int i = 0; i < N - 1; ++i)
    {
      deletedintervals += intervals.at(i);
    }
  }

  cout << coordinates.back() - coordinates.front() - deletedintervals << endl; 

  return 0;
