struct Tree	//create tree(directed) from graph(undirected)
{
    int n;
    int root;
    vector<vector<int>> t;
    vector<int> par;
    vector<int> dpt;

    void init(Graph &g, int root_){
        n = g.n;
        root = root_;
        t.resize(n);
        par.resize(n);
        dpt.resize(n);
        fill(dpt.begin(), dpt.end(), -1);
        queue<int> que;
        par[root] = -1;
        dpt[root] = 0;
        que.push(root);
        while(que.size()){
            int pa = que.front();
            que.pop();
            for(int ch : g.g[pa]){
                if(dpt[ch] == -1){
                    t[pa].push_back(ch);
                    par[ch] = pa;
                    dpt[ch] = dpt[pa] + 1;
                    que.push(ch);
                }
            }
        }
    }

    Tree(){}

    Tree(Graph &g, int root_){
        init(g, root_);
    }
};

template <typename T>
struct WeightedTree
{
    int n;
    int k;
    int root;
    vector<vector<Edge<T>>> t;
    vector<int> par;
    vector<int> dpt;
    vector<vector<int>> v;
    vector<int> p;
    vector<ll> s;
    vector<ll> l;

    void init(WeightedGraph<T> &g, int root_){
        n = g.n;
        k = 0;
        root = root_;
        t.resize(n);
        par.resize(n);
        dpt.resize(n);
        v.resize(n);
        p.resize(n);
        s.resize(n * 2);
        l.resize(n * 2);
        fill(dpt.begin(), dpt.end(), -1);
        fill(p.begin(), p.end(), -1);
        s.push_back(0);
        l.push_back(0);
        for(int i = 0; i < n; i++) v[i].push_back(0);
        queue<int> que;
        par[root] = -1;
        dpt[root] = 0;
        que.push(root);
        while(que.size()){
            int pa = que.front();
            que.pop();
            for(Edge e : g.g[pa]){
                int ch = e.to;
                if(dpt[ch] == -1){
                    t[pa].push_back(e);
                    par[ch] = pa;
                    dpt[ch] = dpt[pa] + 1;
                    que.push(ch);
                }
            }
        }
    }

    WeightedTree(){}

    WeightedTree(WeightedGraph<T> &g, int root_){
        init(g, root_);
    }

    void dfs(int i){
        if(p[i] == -1) p[i] = k;
        k++;
        for(Edge<P> ch : t[i]){
            s[k] = s[v[ch.cost.first][(int)v[ch.cost.first].size() - 1]] + ch.cost.second;
            l[k] = l[v[ch.cost.first][(int)v[ch.cost.first].size() - 1]] + 1;
            v[ch.cost.first].push_back(k);
            dfs(ch.to);
            s[k] = s[v[ch.cost.first][(int)v[ch.cost.first].size() - 1]] - ch.cost.second;
            l[k] = l[v[ch.cost.first][(int)v[ch.cost.first].size() - 1]] - 1;
            v[ch.cost.first].push_back(k);
            k++;
        }
    }
};

vector<ll> Dijkstra(WeightedTree<P> &t, int s){
    int n = t.n;
    vector<ll> d(n);
    fill(d.begin(), d.end(), -1);
    queue<int> que;
    d[s] = 0;
    que.push(s);
    while(que.size()){
        int now = que.front();
        que.pop();
        for(Edge<P> e : t.t[now]){
            d[e.to] = d[now] + e.cost.second;
            que.push(e.to);
        }
    }
    return d;
}

int par[100002][20];

int common(int u, int v, WeightedTree<P> &t){
    if(t.dpt[u] < t.dpt[v]) swap(u, v);
    int r = t.dpt[u] - t.dpt[v];
    for(int j = 0; j < 20; j++){
        if((r >> j) && 1){
            r -= (1 << j);
            u = par[u][j];
        }
    }
    for(int j = 19; j >= 0; j--){
        if(par[u][j] != par[v][j]) u = par[u][j], v = par[v][j];
    }
    return t.par[u];
}

