int minElement(const int* array, size_t size)
{
    int x=0;
    assert(array != NULL);
    assert(size >= 1);

    int min = array[0];
    for (size_t i = 0; i < size; ++i) {
        if (min > array[i]) {
            min = array[i];
            x = i;
        }
    }

    return x;
}


