		for (int j = 0; j < 2*n+1; j++) {
			if(j-dx[i] >= 0) dpx[i][j] = max(dpx[i-1][j-dx[i]], dpx[i][j]);
			if(j+dx[i] < 2*n+1) dpx[i][j] = max(dpx[i-1][j+dx[i]], dpx[i][j]);
		}
	}
	for (int i = 0; i < dy.size(); i++) {
		for (int j = 0; j < 2*n+1; j++) {
			if(j-dy[i] >= 0) dpy[i+1][j] = max(dpy[i][j-dy[i]], dpy[i+1][j]);
			if(j+dy[i] < 2*n+1) dpy[i+1][j] = max(dpy[i][j+dy[i]], dpy[i+1][j]);
		}
	}
	int xx = max((int)dx.size() - 1, 0);
	int yy = max((int)dy.size(), 0);
	if (dpx[xx][x] == 1 and dpy[yy][y] == 1) {
		cout << "Yes" << endl;
