const int hashMod=437935;
node ent[10000000];
int sz;
node* hash[hashMod];

void insert(ll key){
  int ha=key%hashMod;
  for(node*p=hash[ha];p;p=p->next){
    if(p->key==key)return;
  }
  node*p=hash[ha];
  hash[ha]=ent+sz++;
  hash[ha]->key=key;
  hash[ha]->next=p;
}

bool count(ll key){
  int ha=key%hashMod;
  for(node*p=hash[ha];p;p=p->next){
    if(p->key==key)return true;
  }
  return false;
}

