      int nx=i+dx[k],ny=j+dy[k];
      if((0>nx || nx>=n ||
         0>ny || ny>=m ||
          get(st,nx,ny)) &&
         nx!=x && ny!=y)continue;
      ++ne0;
    }
    if(ne0<2){
      //cout<<i<<' '<<j<<' '<<ne0<<' '<<get(st,i,j)<<endl;
      //cout<<"true"<<endl;
      return true;
    }
  }
