  sz=0;
  memset(hash,0,sizeof(hash));
  ll st=0;
  int bu=0;
  rep(i,n){
    rep(j,m){
      ll t;
      cin>>t;
      st|=t<<i*m+j;
      bu+=t;
    }
  }
  rep(i,n)rep(j,m){
    if(get(st,i,j))continue;
    sx=i;
    sy=j;
    break;
  }

  if(bu%2==0 && dfs(st,sx,sy,n*m-bu))cout<<"Yes"<<endl;
  else cout<<"No"<<endl;
}

main(){
  while(cin>>m>>n,n|m)solve();
