#include <iostream>
#include <algorithm>
using namespace std;

const int MAX_N = 10005;
const int INF = 1<<29;
int N;
int Cost[MAX_N];
int T[MAX_N][2][MAX_N/2];

int solve() {
  fill(T[0][0],T[MAX_N][0],INF);
  T[1][0][0] = T[1][1][1] = 0;
  for(int i = 2; i <= N; ++i) {
    for(int j = 0; j < 2; ++j) {
      for(int k = 0; k <= min(i,N/2); ++k) {
	for(int l = 0; l < 2; ++l) {
	  int cost = (j == l ? 0 : Cost[i-2]);
	  if(k-l < 0) continue;
	  T[i][j][k] = min(T[i][j][k], T[i-1][l][k-l]+cost);
	}
      }
    }
  }
  return min(T[N][0][N/2], T[N][1][N/2]);
}

int main() {
  while(cin >> N && N) {
    for(int i = 0; i < N-1; ++i) {
      cin >> Cost[i];
    }
    cout << solve() << endl;
  }
  return 0;
},memory_limit_exceeded,,p00473

