#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
vector<string> a, ans;
string s;

void f(ll b, int d){
  if(d==s.length()){
    string t="";
    for(int i=0; i<s.length(); i++){
      if(b&(1<<i) && s[i]!='z')t.push_back(s[i]+1);
      else t.push_back(s[i]);
    }
    a.push_back(t);
    return;
  }
  f(b|(1<<d), d+1);
  f(b, d+1);
}

bool g(string t){
  int tmp[26];
  memset(tmp, 0, sizeof(tmp));
  for(int i=0; i<t.length(); i++){
    if(tmp[t[i]-'a']==0 && t[i]!='a'){tmp[t[i]-'a']=1; t[i]-=1;}
  }
  if(s==t)return true;
  else return false;
}

