enum Foot{
	Left,
	Right,
};

int H,W;
int***** min_Time;

int diff_row_right[9] = {-2,-1,-1,0,0,0,1,1,2},diff_col_right[9] = {1,1,2,1,2,3,1,2,1};
int diff_row_left[9] = {-2,-1,-1,0,0,0,1,1,2},diff_col_left[9] = {-1,-2,-1,-3,-2,-1,-2,-1,-1};

struct Info{
	Info(){
		left_row = left_col = right_row = right_col = time = 0;
		foot = Left;
	}

	Info(int arg_left_row,int arg_left_col,int arg_right_row,int arg_right_col,int arg_time,Foot arg_foot){
		left_row = arg_left_row;
		left_col = arg_left_col;
		right_row = arg_right_row;
		right_col = arg_right_col;
		time = arg_time;
		foot = arg_foot;
	}

	bool operator<(const struct Info &arg) const{
			return time > arg.time;
	};

	void set(int arg_left_row,int arg_left_col,int arg_right_row,int arg_right_col,int arg_time,Foot arg_foot){
		left_row = arg_left_row;
		left_col = arg_left_col;
		right_row = arg_right_row;
		right_col = arg_right_col;
		time = arg_time;
		foot = arg_foot;
	}
	int left_row,left_col,right_row,right_col,time;
	Foot foot;
};

struct Cell{
	Cell(){
		row = col = 0;
	}
	Cell(int arg_row,int arg_col){
		row = arg_row;
		col = arg_col;
	}

	bool operator<(const struct Cell &arg) const{
			return col < arg.col;
	};

	int row,col;
};

bool rangeCheck(int row,int col){
	if(row >= 0 && row <= H-1 && col >= 0 && col <= W-1)return true;
	else{
		return false;
	}
}

void func(){

	for(int a = 0; a < H; a++){
		for(int b = 0; b < W; b++){
			for(int c = 0; c < H; c++){
				for(int d = 0; d < W; d++){
					for(int e = 0; e < 2; e++){
						min_Time[a][b][c][d][e] = BIG_NUM;
					}
				}
			}
		}
	}

	vector<Cell> V;

	char map[H][W+1];
	for(int i = 0; i < H; i++){
		for(int k = 0; k < W; k++){
			scanf("%s",&map[i][k]);
			if(map[i][k] == 'S'){
				V.push_back(Cell(i,k));
				map[i][k] = '0';
			}
		}
	}

	priority_queue<Info> Q;

	int first_left_row,first_left_col,first_right_row,first_right_col,add_time;

	for(int a = 0; a < V.size(); a++){

		first_left_row = V[a].row;
		first_left_col = V[a].col;

		for(int i = 0; i < 9; i++){
			first_right_row = first_left_row + diff_row_right[i];
			first_right_col = first_left_col + diff_col_right[i];

			if(rangeCheck(first_right_row,first_right_col) == true && map[first_right_row][first_right_col] != 'X'){
				if(map[first_right_row][first_right_col] >= '0' && map[first_right_row][first_right_col] <= '9'){
					add_time = map[first_right_row][first_right_col] - '0';
				}else{
					add_time = 0;
				}
				if(min_Time[first_left_row][first_left_col][first_right_row][first_right_col][Right] > add_time){
					min_Time[first_left_row][first_left_col][first_right_row][first_right_col][Right] = add_time;
					Q.push(Info(first_left_row,first_left_col,first_right_row,first_right_col,add_time,Right));
				}
			}
		}

		first_right_row = V[a].row;
		first_right_col = V[a].col;

		for(int i = 0; i < 9; i++){
			first_left_row = first_right_row + diff_row_left[i];
			first_left_col = first_right_col + diff_col_left[i];

			if(rangeCheck(first_left_row,first_left_col) == true && map[first_left_row][first_left_col] != 'X'){
				if(map[first_left_row][first_left_col] >= '0' && map[first_left_row][first_left_col] <= '9'){
					add_time = map[first_left_row][first_left_col] - '0';
				}else{
					add_time = 0;
				}
				if(min_Time[first_left_row][first_left_col][first_right_row][first_right_col][Left] > add_time){
					min_Time[first_left_row][first_left_col][first_right_row][first_right_col][Left] = add_time;
					Q.push(Info(first_left_row,first_left_col,first_right_row,first_right_col,add_time,Left));
				}
			}
		}
	}

	int ans = BIG_NUM,next_left_row,next_left_col,next_right_row,next_right_col;

	while(!Q.empty()){

		if(map[Q.top().left_row][Q.top().left_col] == 'T' || map[Q.top().right_row][Q.top().right_col] == 'T'){
			ans = min(ans,Q.top().time);
			Q.pop();
		}else if(Q.top().time > min_Time[Q.top().left_row][Q.top().left_col][Q.top().right_row][Q.top().right_col][Q.top().foot] || Q.top().time > ans){
			Q.pop();
		}else{

			if(Q.top().foot == Left){
				for(int i = 0; i < 9; i++){
					next_right_row = Q.top().left_row + diff_row_right[i];
					next_right_col = Q.top().left_col + diff_col_right[i];

					if(rangeCheck(next_right_row,next_right_col) == true && map[next_right_row][next_right_col] != 'X'){
						if(map[next_right_row][next_right_col] >= '0' && map[next_right_row][next_right_col] <= '9'){
							add_time = map[next_right_row][next_right_col]-'0';
						}else{
							add_time = 0;
						}
						if(min_Time[Q.top().left_row][Q.top().left_col][next_right_row][next_right_col][Right] > Q.top().time+add_time){
							min_Time[Q.top().left_row][Q.top().left_col][next_right_row][next_right_col][Right] = Q.top().time+add_time;
							Q.push(Info(Q.top().left_row,Q.top().left_col,next_right_row,next_right_col,Q.top().time+add_time,Right));
						}
