							Q.push(Info(next_left_row,next_left_col,Q.top().right_row,Q.top().right_col,Q.top().time+add_time,Left));
						}
					}
				}
			}

			Q.pop();
		}

	}

	if(ans == BIG_NUM){
		printf("-1\n");
	}else{
		printf("%d\n",ans);
	}
}

