							}
						}
						if(bOK){
							q2.push(P2(e.first + t.length(), edge[e.second][i].second));
						}
					}
				}
				if(!bMin) break;
			}
			if(bMin) cout << goal << endl;
			else cout << "NO" << endl;
		}	
		rep(i, 0, n) edge[i].clear();
		while(!q.empty()) q.pop();
	}

}

