using namespace std;

typedef long long ll;
typedef pair<int, string> pr;
typedef pair<pair<int, int>, int> tup;

int sol(int i, int j, string &s1, string &s2, string k, vector<vector<pr>> &dp)
{
	if (i >= s1.size() || j >= s2.size())
	{
		dp[i][j] = { 0, "" };
		return 0;
	}
	if (dp[i][j].first != -1)
	{
		return dp[i][j].first;
	}

	if (s1[i] == s2[j])
	{
		int a = sol(i + 1, j + 1, s1, s2, k, dp);
		dp[i][j] = { a + 1, s1[i] + dp[i + 1][j + 1].second };
	}
	else
	{
		string s3 = k, s4 = k;
		int a = sol(i, j + 1, s1, s2, s3, dp);
		int b = sol(i + 1, j, s1, s2, s4, dp);
		if (a >= b)
		{
			dp[i][j] = { a, dp[i][j + 1].second };
		}
		else
			dp[i][j] = { b, dp[i + 1][j].second };
	}
	return dp[i][j].first;
}

inline void solve()
{
	string s1, s2;
	cin >> s1 >> s2;
	string res = "";
	vector<vector<pr>> dp(s1.size() + 1, vector<pr>(s2.size() + 1, { -1, "" }));
	sol(0, 0, s1, s2, res, dp);
	cout << dp[0][0].second;
}

int main()
{
	fast;
#if defined(_DEBUG)
	freopen("input.txt", "r", stdin);
	freopen("output.txt", "w", stdout);
#endif
	solve();
