const int MAX_N = 24;
int N;
int color[MAX_N];
int ride[MAX_N];
int x[MAX_N];
int y[MAX_N];
int r[MAX_N];

bool isCollision ( int x1, int y1, int r1, int x2, int y2, int r2 )
{
	int xx = x1 - x2, yy = y1 - y2, rr = r1 + r2;
	return (xx * xx + yy * yy) < (rr * rr);
}

int dfs ( int state, int depth )
{
	if (depth == N/2) { return 0; }
	int res = 0;
	for (int i = 0; i < N; ++i) {
		if ((state & (1 << i)) && !(state & ride[i])) {
			for (int j = i+1; j < N; ++j) {
				if ((state & (1 << j)) && !(state & ride[j]) && color[i] == color[j]) {
					int next = state & ~((1 << i) | (1 << j));
					res = max(res, dfs(next, depth+1) + 2);
				}
			}
		}
	}
	return res;
}

int d[1 << MAX_N];

int main ( void )
{
	while (cin >> N, N) {
		fill(ride, ride+N, 0);
		rep (i, 0, N) {
			cin >> x[i] >> y[i] >> r[i] >> color[i];
			rep (j, 0, i) {
				if (isCollision(x[i], y[i], r[i], x[j], y[j], r[j])) {
					ride[i] |= (1 << j);
				}
			}
		}
		fill(d, d+(1 << N), -1);
		int state = (1 << N) - 1, ans = 0;
		d[state] = 0;
		for (; state > 0; --state) {
			if (d[state] == -1) { continue; }
			rep (i, 0, N) {
				if (state & (1 << i) && !(state & ride[i])) {
					rep (j, i+1, N) {
						if (state & (1 << j) && !(state & ride[j]) && color[i] == color[j]) {
							int next = state & ~((1 << i) | (1 << j));
							d[next] = max(d[next], d[state] + 2);
							ans = max(ans, d[next]);
						}
					}
				}
			}
		}
		cout << ans << endl;
		//cout << dfs((1 << N) - 1, 0) << endl;
	}
	return 0;
