#include <algorithm>

using namespace std;

int dp[3001][3001];

struct Tag {
    int t, n, val;

    Tag() {}
    Tag(int t, int n, int val) : t(t), n(n), val(val) {}

    bool operator <(const Tag &other) const {
        return t > other.t;
    }
};

int main() {
    ios::sync_with_stdio(0);

    int N, T, S;
    cin >> N >> T >> S;

    vector<pair<int,int> > xs(N);
    for(int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        xs[i] = make_pair(x, y);
    }

    for(int i = 0; i < 3001; ++i) 
        for(int j = 0; j < 3001; ++j)
            dp[i][j] = -1;

    int ans = 0;
    priority_queue<Tag> q;
    q.push(Tag(0, 0, 0));
    while(!q.empty()) {
        Tag t = q.top();
        q.pop();

        if(dp[t.t][t.n] >= t.val) continue;
        //cout << t.t << ' ' << t.n << ' ' << t.val << endl;
        dp[t.t][t.n] = t.val;
        ans = max(ans, t.val);

        {
            int nt = t.t+1;
            if(nt <= T && dp[nt][t.n] < t.val) {
                q.push(Tag(nt, t.n, t.val));
            }
        }
        for(int i = t.n; i < N; ++i) {
            int nv = t.val + xs[i].first;
            int nt = t.t + xs[i].second;
            if(nt > T) continue;
            if(t.t < S && nt > S) continue; //花火を見ないといけない
            if(dp[nt][i+1] >= nv) continue;
            q.push(Tag(nt, i+1, nv));
        }
    }

    cout << ans << endl;
    return 0;
},memory_limit_exceeded,,p00496

