		for (int i = 0; i < v.size(); i++) can[v[i]] = false, vis[v[i]] = false;
		return;
	}
	vis[pos] = cur;
	v.push_back(pos);
	int nxt = pos + p[pos];
	if (p[nxt] == 0 || nxt == n - 1) return;
	rec(nxt, cur);
}
