};
uint32_t encode(array<point_t,3> const & s) {
    uint32_t q = 0;
    for (point_t p : s) {
        q = (q * 18) + p.y;
        q = (q * 16) + p.x;
    }
    return q;
}
bool is_valid_move(int i, int j, array<point_t,3> const & s, array<point_t,3> const & t) {
    if (t[i] == t[j]) return false;
    if (t[i] == s[j] and t[j] == s[i]) return false;
    return true;
}

int main() {
