            c.push_back(w);
            h += 2;
        }

        set<uint32_t> used;
        queue<state_t> que; {
            state_t initial = { start, 0 };
            used.insert(encode(start));
            que.push(initial);
        }
        while (not que.empty()) {
            state_t st = que.front(); que.pop();
            array<point_t,3> & s = st.a;
            if (s == goal) {
                cout << st.cost << endl;
                break;
            }
            state_t tt = st;
            tt.cost += 1;
            array<point_t,3> & t = tt.a;
            repeat (i,5) { // a
                t[0] = s[0] + dp[i];
                if (c[t[0].y][t[0].x] == '#') continue;
                repeat (j,5) { // b
                    t[1] = s[1] + dp[j];
                    if (c[t[1].y][t[1].x] == '#') continue;
                    if (not is_valid_move(0, 1, s, t)) continue;
                    repeat (k,5) { // c
                        t[2] = s[2] + dp[k];
                        if (c[t[2].y][t[2].x] == '#') continue;
                        if (not is_valid_move(1, 2, s, t)) continue;
                        if (not is_valid_move(2, 0, s, t)) continue;
                        if (used.count(encode(t))) continue;
                        used.insert(encode(t));
                        que.push(tt);
                    }
                }
            }
        }
    }
    return 0;
