int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};
int field[12][12];
int nums[12][12];
map<P, bool> ng;

int dfs(int state, int x, int y){
  if(ng[P(state, nums[y][x])]) return 0;
  if(state == 0){
    rep(i, 4){
      int x2 = x + dx[i];
      int y2 = y + dy[i];
      while(field[y2][x2] == 0){
	y2 += dy[i];
	x2 += dx[i];
      }
      if(field[y2][x2] == 2) return 1;
    }
    ng[P(state, nums[y][x])] = true;
    return 0;
  }
  int res = 0;
  rep(i, 4){
    int x2 = x + dx[i];
    int y2 = y + dy[i];
    while(field[y2][x2] != 3){
      if(field[y2][x2] == 1){
	field[y2][x2] = 3;
	res += dfs(state - (1 << nums[y2][x2]), x2, y2);
	field[y2][x2] = 1;
      }
      x2 += dx[i];
      y2 += dy[i];
    }
  }
  if(res == 0) ng[P(state, nums[y][x])] = true;
  return res;
}


int main(){
  int n, m, sx, sy, cnt;
  while(cin >> m >> n && (n || m)){
    cnt = 0;
    fill(&field[0][0], &field[11][11] + 1, 3);
    memset(nums, 0, sizeof(nums));
    ng.clear();
    rep(i, n){
      rep(j, m){
	cin >> field[i+1][j+1];
	if(field[i+1][j+1] == 2){
	  sx = j + 1;
	  sy = i + 1;
	}
	if(field[i+1][j+1] == 1){
	  nums[i+1][j+1] = cnt++;
	}
      }
    }
    cout << dfs((1 << cnt) - 1, sx, sy) << endl;
  }
  return 0;
}
