struct CumulativeSum2D {
	int h;
	int w;
	std::vector<std::vector<ll>> grid_;
	CumulativeSum2D(std::vector<std::vector<ll>>& source) : h(source.size()), w(source[0].size()) {
		grid_.assign(h + 1, std::vector<ll>(w + 1, 0));
		for (int i = 0; i < h; ++i)
			for (int j = 0; j < w; ++j)
				grid_[i + 1][j + 1] = grid_[i][j + 1] + grid_[i + 1][j] - grid_[i][j] + source[i][j];
	}
	ll get_from_size(int left, int top, int width, int height) {
		return grid_[top + height][left + width] - grid_[top][left + width] - grid_[top + height][left] + grid_[top][left];
	}

	ll get_from_ltrb(int left, int top, int right, int bottom) {
		return get_from_size(left, top, right - left + 1, bottom - top + 1);
	}
};

