#include<bits/stdc++.h>
using namespace std;

int xor128(void)
{ 
  static int x = 123456789;
  static int y = 362436069;
  static int z = 521288629;
  static int w = 88675123; 
  int t;

  t = x ^ (x << 11);
  x = y; y = z; z = w;
  return w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
}

struct Node {
  int Value;
  int Data;
  int SubTreeSize;
  Node *Lch, *Rch;
  int RMQ;

  Node(int V, int T):Value(V), Data(T), SubTreeSize(1), RMQ(T) {
    Lch = (Node *)NULL;
    Rch = (Node *)NULL;
  };
};
inline int Count(Node *t)
{
  if(t == (Node *)NULL) return(0);
  else return(t -> SubTreeSize);
}

inline int Sum(Node *t)
{
  if(t == (Node *)NULL) return(0);
  else return(t -> RMQ);
}
inline Node *Update(Node *t)
{
  t -> SubTreeSize = Count(t -> Lch) + Count(t -> Rch) + 1;
  t -> RMQ = max(Sum(t -> Lch), max(Sum(t -> Rch), t -> Data));
  return(t);
}

inline Node *MakeRoot(int value, int T)
{
  return(new Node(value, T));
}

Node *Merge(Node *l, Node *r)
{
  if(l == (Node *)NULL) return(r);
  if(r == (Node *)NULL) return(l);
  int Left  = l -> SubTreeSize;
  int Right = r -> SubTreeSize;
  if(xor128() % (Left + Right) < Left) {
    l -> Rch = Merge(l -> Rch, r);
    return(Update(l));
  } else {
    r -> Lch = Merge(l, r -> Lch);
    return(Update(r));
  }
}

pair< Node*, Node* > Split(Node *t, int k) // [0, k), [k, n)
{
  if(t == (Node *)NULL) return(make_pair((Node *)NULL, (Node *)NULL));
  if(k <= Count(t -> Lch)) {
    pair< Node *, Node *> s = Split(t -> Lch, k);
    t -> Lch = s.second;
    return(make_pair(s.first, Update(t)));
  } else {
    pair< Node *, Node *> s = Split(t -> Rch, k - Count(t -> Lch) - 1);
    t -> Rch = s.first;
    return(make_pair(Update(t), s.second));
  }
}

Node *Insert(Node *root, int pos, int value, int T)
{
  Node *p = MakeRoot(value, T);
  pair< Node *, Node *> s = Split(root, pos);
  return(Merge(Merge(s.first, p), s.second));
}

int Lower_Bound(Node *root, int Value)
{
  if(root == (Node *)NULL) return(0);
  if(Value < root -> Value) return(Lower_Bound(root -> Lch, Value));
  return(Lower_Bound(root -> Rch, Value) + Count(root -> Lch) + 1);
}

Node *Insert(Node *root, int Value, int T)
{
  return(Insert(root, Lower_Bound(root, Value), Value, T));
}

struct MatrixSegmentTree
{
  vector< Node* > node;
  int sz;

  MatrixSegmentTree(int n)
  {
    sz = 1;
    while(sz < n) sz <<= 1;
    node.resize(2 * sz - 1);
    for(int i = 0; i < 2 * sz - 1; i++) {
      node[i] = (Node *)NULL;
    }
  }

  int MatrixMax(int a, int b, int x, int k, int l, int r)
  {
    if(a >= r || b <= l) {
      return(0);
    } else if(a <= l && r <= b) {
      auto p = Split(node[k], Lower_Bound(node[k], x - 1));
      int maximum = Sum(p.first);
      node[k] = Merge(p.first, p.second);
      return(maximum);
    } else {
      int LL = MatrixMax(a, b, x, 2 * k + 1, l, (l + r) >> 1);
      int RR = MatrixMax(a, b, x, 2 * k + 2, (l + r) >> 1, r);
      return(max(LL, RR));
    }
  }

  int MatrixMax(int a, int b)
  {
    return(MatrixMax(0, a, b, 0, 0, sz));
  }

  void PointUpdate(int k, int b, int val)
  {
    k += sz - 1;
    node[k] = Insert(node[k], b, val);
    while(k > 0) {
      k = (k - 1) >> 1;
      node[k] = Insert(node[k], b, val);
    }
  }
};

inline int r(int& a, int& b)
{
  int C = ~(1<<31), M = (1<<16)-1;
  a = 36969 * (a & M) + (a >> 16);
  b = 18000 * (b & M) + (b >> 16);
  return (C & ((a << 16) + b)) % 1000000;
}

