      g.emplace_back(x, -y, -z);
    }
    for(int i = m; i < m + n; i++) {
      g.emplace_back(r(a, b), -r(a, b), -r(a, b));
    }
    n += m;
    sort(g.begin(), g.end());

    // O(n log^2 n)
    MatrixSegmentTree tree(1000000);
    int ret = 0;
    for(int i = 0; i < g.size(); i++) {
