int init(int k){
	int sz=1;
	while(sz<k)sz*=2;
	return sz;
}

void update(vector<long long int> &seg,int k,int a){
	k+=(seg.size()/2)-1;
	seg[k]=a;
	while(k>0){
		k=(k-1)/2;
		seg[k]=min(seg[k*2+1],seg[k*2+2]);
	}
}

long long int query(vector<long long int> &seg,int a,int b,int k,int l,int r){
	if(r<=a || b<=l)return INF;
	if(a<=l && r<=b)return seg[k];
	else{
		long long int vl=query(seg,a,b,k*2+1,l,(l+r)/2);
		long long int vr=query(seg,a,b,k*2+2,(l+r)/2,r);
		return min(vl,vr);
	}
}

