using namespace std;
typedef long long ll;
typedef pair<int,int> pii;
typedef vector<int> vi;

typedef vector< pair<vi,vi> > TD;
//first: child of tree, second: bag

const ll mod = 1e6+3;
set<ll> is_edge;

/*Tree Decomposition for a graph with small treewidth.*/
inline TD heuristic_tree_decomposition(vector<vi> &g){
  int n = g.size();
  TD res = TD(n);
  vi use(n,-1), deg(n);

  priority_queue<pii> q;
  set<ll> tmp_edge = is_edge;
  rep(i,n){
    deg[i] = g[i].sz; deg[i]*=-1;
    q.push(pii(deg[i],i));
  }

  int id = n-1;
  while(q.sz){
    int v = q.top().sc, d = q.top().fs; q.pop();
    if(use[v]!=-1 || deg[v] != d)continue;

    vi unuse;
    for(int u : g[v]){
      if(use[u]==-1)unuse.push_back(u);
      else if(use[u]>=0){
	res[id].first.push_back(use[u]);
	use[u] = -2;
      }
    }

    res[id].second.push_back(v);
    for(int a : unuse){
      res[id].second.push_back(a);
      deg[a]++;
      for(int b :unuse){
	int aa = a, bb = b;
	if(aa>bb)swap(aa,bb);
	if(aa!=bb && !tmp_edge.count(aa*mod + bb)){
	  g[aa].pb(bb);
	  g[bb].pb(aa);
	  tmp_edge.insert(aa*mod + bb);
	  deg[aa]--; deg[bb]--;
	}
      }
    }
    for(int u: unuse)q.push(pii(deg[u],u));

    use[v] = id;
    id--;
  }

  return res;
}

inline void toNice(TD &t, int id){
  stack<int> s;
  s.push(id);

  while(s.sz){
    id = s.top(); s.pop();

    //for join
    while(t[id].first.size()>2){
      vi child(2);
      child[0] = t[id].first.back(); t[id].first.pop_back();
      child[1] = t[id].first.back(); t[id].first.pop_back();
      t.push_back(make_pair(child, t[id].second));
      t[id].first.push_back(t.size()-1);
    }

    if(t[id].first.size()==2){
      rep(i,2){
	const int &j = t[id].first[i];
	if(t[id].second != t[j].second){
	  vi child(1);
	  child[0] = j;
	  t.push_back(make_pair(child, t[id].second));
	  t[id].first[i] = t.size()-1;
	}
      }
    }

    //for introduce & forget
    if(t[id].first.size()==1){
      const int &j = t[id].first[0];
      vi child(1);
      child[0] = j;

      vi disA, disB;
      rep(a,t[id].second.size()){
	bool f = true;
	rep(b,t[j].second.size()){
	  if(t[id].second[a] == t[j].second[b])f = false;
	}
	if(f)disA.push_back(a);
      }
      rep(b,t[j].second.size()){
	bool f = true;
	rep(a,t[id].second.size()){
	  if(t[id].second[a] == t[j].second[b])f = false;
	}
	if(f)disB.push_back(b);
      }

      if(disA.size() + disB.size() > 1){
	if(disA.size()>0){
	  vi tmp = t[id].second;
	  tmp.erase(tmp.begin() + disA[0]);
	  t.push_back(make_pair(child, tmp));
	  t[id].first[0] = t.size()-1;
	}else{
	  vi tmp = t[id].second;
	  tmp.push_back(t[j].second[disB[0]]);
	  t.push_back(make_pair(child, tmp));
	  t[id].first[0] = t.size()-1;
	}      
      }
    }

    //for leaf
    if(t[id].first.size() == 0){
      if(t[id].second.size() > 1){
	vi tmp;
	rep(i,t[id].second.size()-1)tmp.push_back(t[id].second[i]);
	t.push_back(make_pair(vi(), tmp));
	t[id].first.push_back(t.size()-1);
      }
    }

    rep(i,t[id].first.size()){
      s.push(t[id].first[i]);
    }
  }
}

unordered_map<ll,ll> memo;

ll rec(int id, int use, const TD &t){
  ll key = mod*id + use;

  stack<ll> s;
  s.push(key);

  while(s.sz){
    ll res = 0;
    key = s.top(); s.pop();
    id = key/mod; use = key%mod;
    const vi& child = t[id].fs, bag = t[id].sc;

    //for leaf
    if(child.sz==0){
      memo[key] = use;
      goto END;
    }

    if(child.sz==1){
      const vi &nbag = t[child[0]].second;
      vi to_bag(nbag.size(),-1), to_nbag(bag.size(),-1);
      rep(i,bag.size())rep(j,nbag.size()){
	if(bag[i] == nbag[j]){
	  to_bag[j] = i; to_nbag[i] = j;
	}
      }

      //for introduce
      if(nbag.sz < bag.sz){
	int nuse = 0;
	rep(i,bag.sz){
	  if(to_nbag[i]<0){
	    if( ((use>>i)&1) == 0 ){
	      memo[key] = 0;
	      goto END;
	    }
	  }else{
	    if( ((use>>i)&1) )nuse |= 1<<to_nbag[i];
	  }
	}
	ll nxt = child[0]*mod + nuse;
	if(memo.count(nxt)){
	  memo[key] = memo[nxt];
	  goto END;
	}else{
	  s.push(key); s.push(nxt);
	  goto END;
	}
      }

      //for forget
      if(nbag.sz > bag.sz){
	int add = -1,  nuse = 0;
	rep(i,nbag.sz){
	  if(to_bag[i]<0)add = i;
	  else if( (use>>to_bag[i])&1 )nuse |= 1<<i;
	}

	queue<ll> uncal;
	ll res = 0, nxt = child[0]*mod + nuse;
	if(memo.count(nxt)){
	  (res += memo[nxt]) %= mod;
	}else{
	  uncal.push(nxt);
	}

	rep(i,bag.sz){
	  if((use>>i)&1)continue;

	  int a = bag[i], b = nbag[add];
	  if(a>b)swap(a,b);
	  if(is_edge.count(a*mod + b)){
	    nxt = child[0]*mod + (nuse | (1<<add) | (1<<to_nbag[i]));
	    if(memo.count(nxt)){
	      (res += memo[nxt]) %= mod;
	    }else{
	      uncal.push(nxt);
	    }
	  }
	}

	if(uncal.sz){
	  s.push(key); while(uncal.sz){ s.push(uncal.front()); uncal.pop(); }
	  goto END;
	}else{
	  memo[key] = res;
	  goto END;
	}
      }
    }

    //for join
    if(child.sz==2){
      int n = bag.sz, unuse = (1<<n)-1 - use, sub = unuse;
      queue<ll> uncal;
      do{
	ll nxt1 = child[0]*mod + (use|sub), nxt2 = child[1]*mod + (use|(unuse-sub));
	if(memo.count(nxt1) == 0){
	  uncal.push(nxt1);
	}
	if(memo.count(nxt2) == 0){
	  uncal.push(nxt2);
	}
	if(memo.count(nxt1) && memo.count(nxt2)){
	  res += memo[nxt1] * memo[nxt2];
	  res %= mod;
	}
	sub = (sub-1)&unuse;
      }while(sub != unuse);

      if(uncal.sz){
	s.push(key); while(uncal.sz){ s.push(uncal.front()); uncal.pop(); }
	goto END;
      }else{
	memo[key] = res;
	goto END;
      }
    }
  END:;
  }
  return memo[key];
}

