// compare (rank[i],rank[i+k]) and (rank[j],rank[j+k])
bool compare_sa(int i,int j)
{
	int ri,rj;
	if (rank[i]!=rank[j])
	{
		return rank[i]<rank[j];
	}
	else
	{
		if (i+k<=n)
		{
			ri=rank[i+k];
		}
		else
		{
			ri=-1;
		}
		if (j+k<=n)
		{
			rj=rank[j+k];
		}
		else
		{
			rj=-1;
		}
		return ri<rj;
	}
}

void construct_sa(string s,int *ta)
{
	int i;
	n=s.length();
	//for those of length 1, get it's char
	for (i=0;i<=n;i++)
	{
		ta[i]=i;
		if (i<n)
		{
			rank[i]=s[i];
		}
		else
		{
			rank[i]=-1;
		}
	}
	//for those of length 2*k, use the result of length k
	for (k=1;k<=n;k*=2)
	{
		sort(ta,ta+n+1,compare_sa);

		//store the new rank[] in tmp[]
		tmp[ta[0]]=0;
		for (i=1;i<=n;i++)
		{
			if (compare_sa(ta[i-1],ta[i]))
			{
				tmp[ta[i]]=tmp[ta[i-1]]+1;
			}
			else
			{
				tmp[ta[i]]=tmp[ta[i-1]];
			}
		}
		//copy tmp[] back to rank[]
		for (i=0;i<=n;i++)
		{
			rank[i]=tmp[i];
		}
	}
}

