#include <iostream>
#include <algorithm>
using namespace std;
using int64 = int64_t;

const int64 INF = 1e18;

inline void fastin(int64 &num){
  int64 c;
  num = 0;
  c = getchar_unlocked();
  for (; (c > 47 && c < 58); c = getchar_unlocked()) num = (num << 3) + (num << 1) + c - 48;
}

inline void fastout(int64 n){
  int64 N = n, rev, count = 0;
  rev = N;
  if (N == 0) {putchar_unlocked('0'); putchar_unlocked('\n'); return;}
  while ((rev % 10) == 0) {++count; rev /= 10;}
  rev = 0;
  while (N != 0) {rev = (rev << 3) + (rev << 1) + N % 10; N /= 10;}
  while (rev != 0) {putchar_unlocked(rev % 10 + '0'); rev /= 10;}
  while (--count) putchar_unlocked('0');
}

int main(){
  int64 a, b, q; fastin(a), fastin(b), fastin(q);
  int64 s[a + 2], t[b + 2];

  s[0] = -1 * INF; t[0] = -1 * INF; s[a + 1] = INF; t[b + 1] = INF;

  for (int i = 1; i <= a; ++i) fastin(s[i]);
  for (int i = 1; i <= b; ++i) fastin(t[i]);

  for (int i = 0; i < q; ++i){
    int64 x; fastin(x);
    auto pos1 = lower_bound(s, s + a + 2, x);
    auto pos2 = lower_bound(t, t + b + 2, x);

    int64 ans = min({max(*pos1 - x, *pos2 - x), 
		     max(x - *(pos1 - 1), x - *(pos2 - 1)),
		     2 * (*pos1 - x) + x - *(pos2 - 1),
		     *pos1 - x + 2 * (x - *(pos2 - 1)),
		     2 * (*pos2 - x) + x - *(pos1 - 1),
		     *pos2 - x + 2 * (x - *(pos1 - 1))}); 
    fastout(ans); putchar_unlocked('\n');
  }

  return 0;
}
