						Q.top().num_move > info[Q.top().row][Q.top().col][Q.top().dir].num_move)){

			Q.pop();

		}else if(Q.top().row == goal_row && Q.top().col == goal_col){

			printf("%d\n",Q.top().num_turn);
			return 0;

		}else{

			//向きを変える
			for(int i = 0; i < 4; i++){

				next_dir = type_dir[i];

				switch(next_dir){
				case North:
					next_row = Q.top().row-1;
					next_col = Q.top().col;
					break;
				case East:
					next_row = Q.top().row;
					next_col = Q.top().col+1;
					break;
				case South:
					next_row = Q.top().row+1;
					next_col = Q.top().col;
					break;
				case West:
					next_row = Q.top().row;
					next_col = Q.top().col-1;
					break;
				}

				if(rangeCheck(next_row,next_col) && table[next_row][next_col] != '@'){

					if(next_dir == Q.top().dir && Q.top().num_turn < K){

						next_turn = Q.top().num_turn;
						next_move = Q.top().num_move+1;

					}else{

						next_turn = Q.top().num_turn+1;
						next_move = 1;
					}

					if((info[next_row][next_col][next_dir].num_turn > next_turn) ||
							(info[next_row][next_col][next_dir].num_turn == next_turn &&
									info[next_row][next_col][next_dir].num_move < next_move)){

						info[next_row][next_col][next_dir].num_turn = next_turn;
						info[next_row][next_col][next_dir].num_move = next_move;
						Q.push(State(next_row,next_col,next_turn,next_move,next_dir));
					}
				}
			}
			Q.pop();
		}
	}

	printf("-1\n");

	return 0;
}
