#ifdef MODULAR_ARITHMETIC
template <typename T>
T add(T a, T b, T c) {
  T res = a + b;
  return (res >= c ? res - c : res);
}
template <typename T>
T sub(T a, T b, T c) {
  T res = (a - b) % c;
  return (res < 0 ? res + c : res);
}
template <typename T>
T mul(T a, T b, T c) {
  ll res = (ll)a * b;
  return (res >= c ? res % c : res);
}
template <typename T>
T power(T e, T n, T m) {
  T x = 1, p = e;
  while (n) {
    if (n & 1) x = mul(x, p, m);
    p = mul(p, p, m);
    n >>= 1;
  }
  return x;
}
template <typename T>
T extended_euclid(T a, T b, T &x, T &y) {
  T xx = 0, yy = 1;
  y = 0;
  x = 1;
  while (b) {
    T q = a / b, t = b;
    b = a % b;
    a = t;
    t = xx;
    xx = x - q * xx;
    x = t;
    t = yy;
    yy = y - q * yy;
    y = t;
  }
  return a;
}
template <typename T>
T mod_inverse(T a, T n) {
  T x, y, zero = 0;
  T d = extended_euclid(a, n, x, y);
  return (d > 1 ? -1 : sub(x, zero, n));
}
