void preprocessing() {}

void solvetestcase() {
  ll n, k;
  cin >> n >> k;
  vll p(n), c(n);
  cin >> p >> c;

  ll ans = c[0];
  f(i, 0, n) {
    p[i]--;
    ans = max(ans, c[i]);
  }

  vvi cycles;

  vector<bool> visited(n, 0);
  f(i, 0, n) {
    if (!visited[i]) {
      vi cycle;
      int root = i, cur = p[root];

      cycle.pb(root);
      visited[root] = 1;
      while (cur != root) {
        cycle.pb(cur);
        visited[cur] = 1;
        cur = p[cur];
      }

      cycles.pb(cycle);
    }
  }

  for (vi cycle : cycles) {
    ll m = cycle.size();

    f(start, 0, m) {
      vll sum;
      sum.pb(c[cycle[start]]);
      f(i, 1, m) { sum.pb(sum[i - 1] + c[cycle[(i + start) % m]]); }
      cout << sum;

      f(i, 0, min(m, k)) { ans = max(ans, sum[i]); }

      ll tot_sum = sum[m - 1];
      ll rotation = k / m;
      if (tot_sum > 0 && rotation > 0) {
        ans = max(ans, (rotation - 1) * tot_sum);
        f(i, 0, m) { ans = max(ans, sum[i] + (rotation - 1) * tot_sum); }

        ans = max(ans, rotation * tot_sum);
        f(i, 0, k % m) { ans = max(ans, sum[i] + rotation * tot_sum); }
      }
    }
  }
  cout << ans << endl;
}

int main() {
  fio;
  preprocessing();

  int t = 1;
