void insert( int k )
{
    Node *p_y = NIL;		// ?????¨??????????????????????£?????¨??????????
    Node *p_x = root;

    Node *p_z = (Node *)malloc( sizeof( Node ) );
    p_z->parent = NIL;
    p_z->left   = NIL;
    p_z->right  = NIL;
    p_z->key    = k;

    while ( p_x != NULL ) {
	p_y = p_x;
	if ( k < p_x->key ) { // ???
	    p_x = p_x->left;
	}
	else {
	    p_x = p_x->right;
	}
    }

    p_z->parent = p_y;

    if ( p_y == NULL ) {
	root = p_z;
    }
    else if ( p_z->key < p_y->key ) {
	p_y->left = p_z;
    }
    else {
	p_y->right = p_z;
    }
}


void PreOrder( Node *node, vector<int> &v )
{
    if ( node != NULL ) {
	v.push_back( node->key );
	PreOrder( node->left,  v );
	PreOrder( node->right, v );
    }
}


void InOrder( Node *node, vector<int> &v )
{
    if ( node != NULL ) {
	InOrder( node->left,  v );
	v.push_back( node->key );
	InOrder( node->right, v );
    }
}


