int dx[]={-1,0,1,0};
int dy[]={0,1,0,-1};
void shot(const int ax,const int ay,vector<string>&field,int way){
    int nextx=ax;
    int nexty=ay;
    while(true){
        nextx+=dx[way];
        nexty+=dy[way];
        char& ch(field[nexty][nextx]);
        if(ch=='.')continue;
        else if(ch=='*'){
            ch='.';
            return;
        }else if(ch=='#'){
            return;
        }else if(ch=='-')continue;
        else{
            assert(false);
        }
    }
}
