    int T;cin>>T;
    while(T--){
        int H,W;cin>>H>>W;
        H+=2;
        W+=2;
        vector<string>field(H);
        field[0]=string(W,'#');
        for(int i=0;i<H-2;++i){
            string st;cin>>st;
            field[i+1]="#"+st+"#";
        }
        field[H-1]=string(W,'#');
        int way;
        int tank_x,tank_y;
        string way_mp="<v>^";
        {
            for(int y=0;y<H;++y){
                for(int x=0;x<W;++x){
                    char ch=field[y][x];
                    if(way_mp.find(ch)!=-1){
                        way=way_mp.find(ch);
                        field[y][x]='.';
                        tank_x=x;
                        tank_y=y;
                    }
                }
            }
        }
        int N;cin>>N;
        string move_st;
        cin>>move_st;

        for(auto ch:move_st){
            string move_mp("LDRUS");
            int k=move_mp.find(ch);
            if(k==4){
                shot(tank_x,tank_y,field,way);
            }else{
                way=k;
                int next_tank_x=tank_x+dx[way];
