    if (a + b - 1 > n || n > (long long) a * b) {
        cout << -1 << "\n";
        return;
    }
    vector<long long> res;
    FOR(i, 1, a + 1) {
        res.pb((long long) (b - 1) * a + i);
    }
    int cnt = n - a;
    FORd(i, b - 1, 0) {
        int num = min(a, cnt - i);
        FOR(j, 1, num + 1) {
            res.pb((long long) i * a + j);
        }
    }
    vector<long long> dc = res;
    sort(all(dc));
    FOR(i, 0, n) {
        cout << lower_bound(all(dc), res[i]) - dc.begin() + 1 << " \n"[i == n - 1];
    }
}

int main(int argc, char* argv[]) {
    ios_base::sync_with_stdio(0), cin.tie(0);
    if (argc > 1) {
        assert(freopen(argv[1], "r", stdin));
    }
    if (argc > 2) {
        assert(freopen(argv[2], "wb", stdout));
    }
    chemthan();
    cerr << "\nTime elapsed: " << 1000 * clock() / CLOCKS_PER_SEC << "ms\n";
    return 0;
} 
