#include<bits/stdc++.h>

using namespace std;

typedef struct{
    int idx;
    int v;
    int parent;
    int dep;
    vector<int> children;
}node;

int findParent(vector<node*>tree){
    int n = tree.size();
    for(int i = 0; i < n; i++){
        if(tree[i] -> parent == -1){
            return i;
        }
    }
    return -1;
}

void culcurateDepth(vector<node*>tree){
    int pid = findParent(tree);
    tree[pid] -> dep = 0;
    queue<int> Q;
    for(int i = 0; i < tree[pid] -> v; i++){
        Q.push(tree[pid] -> children[i]);
    }
    while(Q.empty()){
        tree[Q.front()] -> dep = tree[(tree[Q.front()] -> parent)] -> dep + 1;
        for(int i = 0; i < tree[Q.front()] -> v; i++){
            Q.push(tree[Q.front()] -> children[i]);
        }
        Q.pop();
    }
    /*
    while(tree[idx] -> parent != -1){
        idx = tree[idx] -> parent;
        dep++;
    }
    */
}

char* judgeKind(vector<node*> tree, int idx){
    if(tree[idx] -> parent == -1){
        char* kind = new char[5];
        kind = "root";
        return kind;
    }else if(tree[idx] -> v == 0){
        char* kind = new char[5];
        kind = "leaf";        
        return kind;
    }else{
        char* kind = new char[14];
        kind = "internal node";
        return kind;
    }
}

int main(){
    vector<node*> tree;    
    int n;
    scanf("%d", &n);
    for(int i = 0; i < n; i++){
        node* x = new node;
        x -> parent = -1;
        x -> idx = -1;
        x -> v = 0;
        tree.push_back(x);
    }
    for(int i = 0; i < n; i++){
        int idx, v;
        scanf("%d %d", &idx, &v);
        tree[idx] -> idx = idx;
        tree[idx] -> v = v;
        for(int j = 0; j < v; j++){
            int cid;
            scanf("%d", &cid);
            tree[idx] -> children.push_back(cid);
            tree[cid] -> parent = idx;
        }
    }
    //ここまでで木の生成はできた

    culcurateDepth(tree);
    for(int i = 0; i < n; i++){
        int id = tree[i] -> idx;
        int par = tree[i] -> parent;
        int dep = tree[i] -> dep;
        char* kind = judgeKind(tree, i);
        printf("node %d: parent = %d, depth = %d, %s, [", id, par, dep, kind);
        if(tree[i] -> v > 0){
            for(int j = 0; j < tree[i] -> v - 1; j++){
                printf("%d, ", tree[i] -> children[j]);
            }
            printf("%d", tree[i] -> children[tree[i] -> v - 1]);
        }
        printf("]\n");
    }
    return 0;
}
