#include <iostream>
#include <cstdio>
#include <cstring>
#include <algorithm>
#include <vector>
#include <map>
using namespace std;

typedef long long ll;
typedef pair<int, int> P1;
typedef pair<P1, string> P2;

const ll MOD = 1000000007LL;

map<string, int> mp;
vector<string> dp[610];

map<string, int> make(vector<P2> v, int n){   
  for(int i = 0 ; i < 610 ; i++) dp[i].clear();
  dp[0].push_back("");

  for(int i = 0 ; i < v.size() ; i++){
    int a = v[i].first.first;
    int b = v[i].first.second;
    string s = v[i].second;

    for(int j = 0 ; j < dp[a].size() ; j++){
      dp[b].push_back(dp[a][j] + s);
    }
  }

  mp.clear();
  for(int i = 0 ; i < dp[n-1].size() ; i++){
    mp[ dp[n-1][i] ]++;
  }
  return mp;
}

int main(){
  int T;
  cin >> T;
  while(T--){
    int n1, m1;
    cin >> n1 >> m1;

    vector<P2> v1;

    P2 tmp;
    for(int i = 0 ; i < m1 ; i++){
      cin >> tmp.first.first >> tmp.first.second >> tmp.second;
      v1.push_back(tmp);
    }
    sort(v1.begin(), v1.end());

    int n2, m2;
    cin >> n2 >> m2;

    vector<P2> v2;

    for(int i = 0 ; i < m2 ; i++){
      cin >> tmp.first.first >> tmp.first.second >> tmp.second;
      v2.push_back(tmp);
    }
    sort(v2.begin(), v2.end());

    map<string, int> mp1 = make(v1, n1);
    map<string, int> mp2 = make(v2, n2);

    ll ans = 0;

    for(map<string, int>::iterator it = mp1.begin() ; it != mp1.end() ; it++){
      if(it->first == "") continue;

      map<string, int>::iterator it2 = mp2.find(it->first);

      if(it2 == mp2.end()) continue;

      ans += (it->second * it2->second) % MOD;
      ans %= MOD;      
    }    
    cout << ans << endl;
  }
  return 0;
