ll dfs(ll l, ll s){
  ll tmp{};
  if(l == 1){
    if(s == 1) return 0;
    if(s == 2) return 1;
    if(s == 3) return 2;
    if(s == 4) return 3;
    if(s == 5) return 3;
  }
  if(s>0 && pow(2,l+1)-2>=s) tmp += dfs(l-1, min((ll)pow(2,l+1)-3, s-1));
  if(s>pow(2,l+1)-2) tmp += pow(2,l);
  if(s>pow(2,l+1)-1) tmp += dfs(l-1, s-pow(2,l+1)+1);
  cout << l << sp <<tmp << rt;
  return tmp;
}

