template<typename DATA>
class Sparse_Segment_Tree{
  public:
    ll n_;
    unordered_map<ll, DATA> lazy2;

    using F = function<DATA(DATA,DATA)>;
    const F f;
    const DATA init;

    Sparse_Segment_Tree(const F &f, const DATA init) : f(f), init(init){
      n_=1;
      return;
    };

    ~Sparse_Segment_Tree(void){
      return;
    };

    ll get_hash(ll l, ll r){
      return l*2000000001 + r;
    }

    //[a,b)の範囲に対してxを作用させる
    void rangeupdate2(ll a, ll b, DATA x, ll l, ll r){
      if(a<=l && r<=b){
        lazy2[get_hash(l,r)] = f(lazy2[get_hash(l,r)], x);
      }else{
        if(a<(l+r)/2) rangeupdate2(a, b, x, l, (l+r)/2);
        if((l+r)/2<b) rangeupdate2(a, b, x, (l+r)/2, r);
      }
      return;
    }

    void rangeupdate2(ll a, ll b, DATA x){
      while(n_<=b) n_<<=1;
      rangeupdate2(a, b, x, 0, n_);
      return;
    }

    DATA pointquery(ll a, ll l, ll r){
      DATA tmp = init;
      if(lazy2.find(get_hash(l,r))!=lazy2.end()) tmp = lazy2[get_hash(l,r)];
      if(r-l<=1) return tmp;
      if(a<(l+r)/2) return f(tmp, pointquery(a, l, (l+r)/2));
      return f(tmp, pointquery(a, (l+r)/2, r));
    };

    DATA pointquery(ll a){
      if(a<0){
        fprintf(stderr, "Segment_Tree Search Space Error\n");
        fprintf(stderr, "Desired:\n");
        fprintf(stderr, "%lld <= %lld\n", 0, a);
        exit(0);
      }else if(n_<=a){
        return init;
      }
      return pointquery(a, 0, n_);
    };
};

int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll N, Q;
  IN(N,Q);

  auto f = [](ll a, ll b){return min(a,b);};
  Sparse_Segment_Tree<ll> que(f, 0);

  ll Shift = 1000000001;

  REP(i,N){
    ll S, T, X;
    IN(S,T,X);
    que.rangeupdate2(S-X+Shift, T-X+Shift, X-Shift);
  }

  assert(false);

  REP(i,Q){
    ll D;
    IN(D);
    ll X = que.pointquery(D+Shift)+Shift;
    if(X==Shift) X=-1;
    OUT(X);
  }

  return 0;
}
