string SSS(string a,string b){
	int p=0;
	if(a.size()>=b.size()){
		for(int i=0;i<=a.size()-b.size();i++){
			if(a.substr(i,b.size())==b){
				return a;
			}
		}
	}
	for(int i=0;i<=b.size();i++){
		if(i>a.size()){return a.substr(0,a.size()-p)+b;}
		if(a.substr(a.size()-i,a.size())==b.substr(0,i)){p=max(p,i);}
	}
}

