        v[x] = true;
        for(int i = head[x]; i; i = Next[i]){
            int y = ver[i], z = edge[i];
            if(d[y] > d[x] + z){
                d[y] = d[x] + z;
                q.push(make_pair(-d[y], y ));
            }
        }
    }
}

