typedef unsigned long long ll;


ll dp(int index, vector<int> arr, vector<int> &memo)
{
    if( memo[index] != -1)
        return memo[index];
    //cout << index << endl;
    if(index == arr.size()-1 && arr[index] != -1)
        return 1;

    if(arr[index] == -1 )
        return 0;


    ll result = 0;

    if(index <= arr.size()-2)
        if(arr[index+1] != -1)
            result += dp(index+1, arr, memo);

    if(index <= arr.size()-3)
        if(arr[index+2] != -1)
            result += dp(index+2, arr, memo);

    return result;

}

