        rep(i,m){
            if(i == _) continue;
            uf.merge(ed[i][0],ed[i][1],0);
        }

        rep(i,n){
            rep(j,n){
                if(i == j) continue;

                if(!uf.issame(i,j)){
                    jud = true;
                }

            }
        }
        if(jud) ans++;
    }

    cout << ans << endl;
