using namespace std;
typedef long long ll;
int dx[]={0,1,0,-1};
int dy[]={-1,0,1,0};
string mp[101];
int h,w;
ll n;


void move(int x,int y,int dir){
  string str="NESW";
  int visited[101][101];
  ll dis[101][101];
  memset(visited,-1,sizeof(visited));
  visited[y][x]=dir;
  dis[y][x]=0;

  while(n!=0){
    int nx=x+dx[dir];
    int ny=y+dy[dir];
    int flg=1;

    if(nx<0||ny<0||nx>=w||ny>=h||mp[ny][nx]=='#'){
      flg=0;
      dir=(dir+1)%4;
      nx=x,ny=y;
    }

    if(visited[ny][nx]==dir){
      if((dis[y][x]-dis[ny][nx]+1)==0)break;;
      n %=(ll)(dis[y][x]-dis[ny][nx]+1);
      memset(visited,-1,sizeof(visited));
    }

    dis[ny][nx]=dis[y][x]+flg;
    n-=flg;
    visited[ny][nx]=dir;
    x=nx,y=ny;
  }
  cout << y+1 <<" "<<x+1<<" "<<str[dir]<<endl;
}


int main(){
  while(1){
    cin >>h>>w>>n;
    if(!h&&!w&&!n)break;
    for(int i=0;i<h;i++) cin >> mp[i];

    int dir,sx,sy;
    for(int i=0;i<n;i++)
      for(int j=0;j<mp[i].size();j++){
	if(mp[i][j]=='.'||mp[i][j]=='#')continue;
	sx=j,sy=i;
	if(mp[i][j]=='N')dir=0;
	if(mp[i][j]=='E')dir=1;
	if(mp[i][j]=='S')dir=2;
	if(mp[i][j]=='W')dir=3;
      }
    move(sx,sy,dir);
  }
  return 0;
