template<class T1, class T2> inline bool cmax(T1 &a, const T2 &b) {return a<b?(a=b, true):false;}
template<class Type> Type read() {
	Type a;
	bool b;
	unsigned char c;
	while(c=getchar()-48, (c>9)&(c!=253));
	for(a=(b=c==253)?0:c; (c=getchar()-48)<=9; a=a*10+c);
	return b?-a:a;
}
int (*rd)()=read<int>;

struct Item {
	s64 x;
	int y, z;
	bool operator<(const Item &o) const {return x*o.y<y*o.x;}
};
const int N=51;
int p[N], f[N*N*N];
Item item[N];
int main() {
	int n, max, d, vol=0;
	s64 ans=0, cur=0;
	n=rd(), max=rd(), d=rd();
	for(int i=1; i<=n; ++i) {
		item[i].x=rd();
		item[i].y=1;
		if(i>1) p[i]=rd();
	}
	for(int i=n; i>1; --i) {
		item[p[i]].x+=item[i].x;
		item[p[i]].y+=item[i].y;
		item[i].z=d;
	}
	item[1].z=max/item[1].x;
	std::sort(item+1, item+n+1);
	for(int i=1; i<=n; ++i) {
		int t=std::min(item[i].z, n), x=item[i].x, y=item[i].y;
		item[i].z-=t;
		for(int j=1; j<t; j*=2) {
			vol=std::min(max, vol+j*x);
			for(int k=vol; k>=j*x; --k) cmax(f[k], f[k-j*x]+j*y);
			t-=j;
		}
		vol=std::min(max, vol+t*x);
		for(int k=vol; k>=t*x; --k) cmax(f[k], f[k-t*x]+t*y);
	}
	for(int i=vol, j=1, k=max-vol; i>=0; --i, ++k) {
		for(; j<=n&&item[j].x*item[j].z<=k; ++j) {
			cur+=(s64)item[j].y*item[j].z;
			k-=item[j].x*item[j].z;
		}
		if(j<=n) {
			int t=k/item[j].x;
			cur+=(s64)t*item[j].y;
			item[j].z-=t;
			k%=item[j].x;
		}
		cmax(ans, f[i]+cur);
	}
	printf("%lld\n", ans);
	return 0;
}
