#define INTSPACE 11
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin) == NULL) return -1;
    return atoi(_buf);
}
int loadvec(vector<int>& v, int N) {
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin) == NULL) return -1;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    // assert(i <= N);
    return i;
}


vector<bool> vis;

void jet(int v, vector<int>& x, vector<ii>& xx, priority_queue<pair<int,ii>>& pq, const char *x_y) {
    assert(vis[v]);
#ifdef VERBOSE
    printf("jet<%s>: v=%d\n", x_y, v);
    cout << "xx=" << xx << endl;
#endif
    int ix = (int)(lower_bound(ALL(xx), ii(x[v],v)) - xx.begin());
    // if (xx[ix].second != v) ++ix;
    //printf("ix=%d/%d; (%d %d) vs (%d %d)\n", ix,(int)xx.size(), xx[ix].first,xx[ix].second, x[v],v);
    assert(xx[ix].first == x[v]);
    assert(xx[ix].second == v);

    for (int i=ix-1; i>=0; --i) {
        int a = xx[i].second;
        if (!vis[a]) {
            pq.push(make_pair(-abs(x[a]-x[v]), ii(v,a)));
#ifdef VERBOSE
            printf(" +%d\n", a);
#endif
            break;
        }
    }
    for (int i=ix+1,c=xx.size(); i<c; ++i) {
        int a = xx[i].second;
        if (!vis[a]) {
            pq.push(make_pair(-abs(x[a]-x[v]), ii(v,a)));
#ifdef VERBOSE
            printf(" +%d\n", a);
#endif
            break;
        }
    }
};

int get_nearest(priority_queue<pair<int,ii>>& pq) {
    while (!pq.empty()) {
        int u = pq.top().second.first, v = pq.top().second.second;
#ifdef VERBOSE
        printf("u=%d, v=%d\n", u, v);
#endif
        assert(vis[u]);
        if (vis[v]) {
            pq.pop(); continue;
        } else {
            return -pq.top().first;
        }
    }
    return INT_MAX;
};

ll solve(int n, vector<int>&x, vector<int>&y) {
    assert(x.size() == n && y.size() == n);

    vis.assign(n, false);
    // vector<bool> vis(n, false);
    vector<ii> xx(n), yy(n);
    rep(i, n) {
        xx[i] = ii(x[i], i);
        yy[i] = ii(y[i], i);
    }
    sort(ALL(xx));
    sort(ALL(yy));

    priority_queue<pair<int,ii>> pqx, pqy;

    vis[0] = true;
    ll cost = 0;
    jet(0, x,xx,pqx, "x");
    jet(0, y,yy,pqy, "y");

    for (int z=1; z<n; ++z) {
#ifdef VERBOSE
        printf("z=%d\n", z);
#endif
        int x_nearest = get_nearest(pqx);
        int y_nearest = get_nearest(pqy);
        if (x_nearest == INT_MAX && y_nearest == INT_MAX) {
            assert(false);
            break;
        }
#ifdef VERBOSE
        printf("nearest=%d or %d\n", x_nearest, y_nearest);
#endif
        int v, a, d;
        if (x_nearest < y_nearest) {
            v = pqx.top().second.first; a = pqx.top().second.second;
            pqx.pop();
            //return ii(v, a);
            //ii va = fn0(vis, pqx);
            //v = va.first; a = va.second;
            d = x_nearest;
        } else {
            v = pqy.top().second.first; a = pqy.top().second.second;
            pqy.pop();
            d = y_nearest;
        }

        assert(vis[v] && !vis[a]);
#ifdef VERBOSE
        printf("take (%d-)%d. cost += %d.\n", v, a, d);
#endif
        vis[a] = true;
        cost += d;

        jet(a, x,xx,pqx, "x");
        jet(a, y,yy,pqy, "y");
    }
    return cost;
}

int main(){
    int N = loadint();
    vector<int> tmp(2);

    vector<int> x(N), y(N);
    rep(i, N) {
        loadvec(tmp, 2);
        x[i]=tmp[0]; y[i]=tmp[1];
    }
    printf("%lld\n", solve(N, x, y));

    return 0;
}
