#ifndef ___CLASS_MODINT
#define ___CLASS_MODINT

#include <cstdint>

template<std::uint32_t mod>
class modint {
private:
	std::uint32_t n;
public:
	modint() : n(0) {};
	modint(std::uint64_t n_) : n(n_ % mod) {};
	bool operator==(const modint& m) const { return n == m.n; }
	bool operator!=(const modint& m) const { return n != m.n; }
	std::uint32_t get() const { return n; }
	modint& operator+=(const modint& m) { n += m.n; n = (n < mod ? n : n - mod); return *this; }
	modint& operator-=(const modint& m) { n += mod - m.n; n = (n < mod ? n : n - mod); return *this; }
	modint& operator*=(const modint& m) { n = std::uint64_t(n) * m.n % mod; return *this; }
	modint operator+(const modint& m) const { return modint(*this) += m; }
	modint operator-(const modint& m) const { return modint(*this) -= m; }
	modint operator*(const modint& m) const { return modint(*this) *= m; }
	modint binpow(std::uint64_t b) const {
		modint ans = 1, m = modint(*this);
		while (b) {
			if (b & 1) ans *= m;
			m *= m;
			b >>= 1;
		}
		return ans;
	}
	modint inv() { return (*this).binpow(mod - 2); }
};

#endif // ___CLASS_MODINT

#include <string>
#include <vector>
#include <cassert>
#include <iostream>
#include <algorithm>
using namespace std;
using modulo = modint<1000000007>;
const int inf = 1012345678;
int solve(int N, int M, string S) {
	if (S[0] == 'B') {
		for (int i = 0; i < M; ++i) {
			if (S[i] == 'B') S[i] = 'R';
			else S[i] = 'B';
		}
	}
	int pre = 0, mn = inf; bool bluemove = true;
	for (int i = 1; i < M; ++i) {
		if (S[i - 1] != S[i]) {
			if (S[i - 1] == 'R' && (pre == 0 || (i - pre) % 2 == 1)) {
				mn = min(mn, i - pre + 1);
			}
			if (S[i - 1] == 'B' && (i - pre) % 2 == 1) {
				bluemove = false;
			}
			pre = i;
		}
	}
	if (mn == inf) {
		vector<modulo> fib(N + 3);
		fib[1] = 1;
		for (int i = 2; i <= N + 2; ++i) {
			fib[i] = fib[i - 1] + fib[i - 2];
		}
		modulo ans = fib[N + 2] - fib[N - 2];
		return ans.get();
	}
	else if (bluemove) {
		vector<modulo> dp1(N + 1), dp2(N + 1);
		dp2[0] = 1;
		for (int i = 1; i <= N; ++i) {
			dp1[i] = dp1[i - 1] + dp2[i - 1];
			for (int j = 0; j < i; ++j) {
				if ((i - j) % 2 == 1 && i - j <= mn) {
					dp2[i] += dp1[j];
				}
			}
		}
		modulo ans = dp1[N];
		for (int i = 1; i <= mn && i <= N; i += 2) {
			ans += dp1[N - i] * (i + 1);
		}
		return ans.get();
	}
	else {
		vector<modulo> dp(N + 1);
		dp[1] = 1;
		int lim = (mn + 1) / 2 * 2;
		modulo sum = 1;
		for (int i = 3; i <= N; i += 2) {
			if (i - lim - 2 >= 0) sum -= dp[i - lim - 2];
			dp[i] = sum;
			sum += dp[i];
		}
		modulo ans = 0;
		for (int i = 1; i <= mn && i <= N; i += 2) {
			ans += dp[N - i] * (i + 1);
		}
		return ans.get();
	}
	return -1;
}
int main() {
	int N, M; string S;
	cin >> N >> M >> S;
	cout << solve(N, M, S) << endl;
	return 0;
}
