ll Ceil(ll val, ll div)   { return (val + div - 1) / div; }
ll CeilN(ll val, ll div)  { return Ceil(val, div) * div; }
ll FloorN(ll x, ll n)     { return (x - x % n); }
bool IsOdd(ll x)          { return ((x & 1) == 1); }
bool IsEven(ll x)         { return ((x & 1) == 0); }
template<class T> bool chmax(T& a, T b) { if (a <= b) { a = b; return 1; } return 0; }
template<class T> bool chmin(T& a, T b) { if (a >= b) { a = b; return 1; } return 0; }

/* 素因数分解 */
map<ll, ll> primeFactor(ll n)
{
	map<ll, ll> factMap;

	if ((n % 2) == 0){
		while ((n % 2) == 0) {
			factMap[2]++;
			n = n / 2;
		}
	}

	for (ll i = 3; i <= sqrt(n); i += 2){
		while ((n % i) == 0){
			factMap[i]++;
			n = n / i;
		}
	}

	if (n != 1) {
		factMap[n]++;
	}

	return factMap;
}

/* baseのべき乗を求める */
template<class T>
T getPower(int exponet, int base)
{
	T ans = 1;
	for (int i = 0; i < exponet; i++) {
		ans *= base;
	}
	return ans;
}

void Solve()
{
	ll N;
	cin >> N;
	vector<string> A(N);
	REP(i, N) cin >> A[i];

	vector<P> primePair(N);

	auto getSosuuPari = [](ll val) {
		map<ll, ll> mp = primeFactor(val);
		P res = { mp[2], mp[5] };
		return res;
	};

	REP(i, N) {
		auto one = A[i];
		auto pos = one.find('.');

		ll topVal;
		ll divVal;
		if (pos == string::npos) {
			divVal = 1;
			topVal = stoll(one);
		} else {
			ll strLen = one.size() - pos - 1;
			string join = one.substr(0, pos) + one.substr(pos + 1);
			divVal = getPower<ll>(strLen, 10);
			topVal = stoll(join.c_str());
		}
		while (divVal != 1) {
			if (topVal % 10 != 0) {
				break;
			}
			topVal /= 10;
			divVal /= 10;
		}

		P topPrime = getSosuuPari(topVal);
		P divPrime = getSosuuPari(divVal);
		primePair[i].first = topPrime.first - divPrime.first;
		primePair[i].second = topPrime.second - divPrime.second;
	}

	ll geta = 20;
	VVL matrix(40, VL(40, 0));
	for (auto one : primePair) {
		matrix[one.first + geta][one.second + geta]++;
	}

	ll ans = 0;
	REP(idx, N) {
		auto one = primePair[idx];
		ll fstMin = (one.first * -1) + geta;
		ll secMin = (one.second * -1) + geta;
		REPN(i, fstMin, 40) {
			REPN(j, secMin, 40) {
				ans += matrix[i][j];
			}
		}
		if (0 <= one.first && 0 <= one.second) ans--;
	}

	cout << ans / 2 << endl;
}

// メイン
int main()
{
	cin.tie(nullptr);
	ios_base::sync_with_stdio(false);
	cout << fixed << setprecision(15);
	Solve();
	return 0;
}
