#include <iostream>
#include <list>
#include <map>
#include <algorithm>
using namespace std;
class Sushi {
    unsigned int const id;
    unsigned int const score;
public :
    Sushi(unsigned int _id, unsigned int _score) : id(_id), score(_score) {}
    bool operator<(Sushi const& x) const {
        if (score == x.score) return id < x.id;
        return (score < x.score);
    }

    void output() const {
        cout << id << ' ' << score << endl;
    }

    unsigned int GetId() const {return id;}
    uint64_t GetGap(Sushi const& target) const {
        return score - target.score;
    }

    uint64_t GetScore() const {return score;}
    void show() {
        cout << id << ' ' << score << endl;
    }
};

bool inverse(Sushi const& x, Sushi const& y) {
    return !(x < y);
}

class SushiSelector {
    std::list<Sushi> selected;
    std::map<unsigned int, unsigned int> counter;
    uint64_t scores;
public :
    SushiSelector() : scores(0) {}

    void add(Sushi& target) {
        selected.push_back(target);
        unsigned int const id = target.GetId();
        if (counter.find(id) == counter.end()) {
            counter[id] = 1;
        } else {
            counter[id]++;
        }
        scores += target.GetScore();
    }

    void erase(auto ite) {
        unsigned int id = ite->GetId();
        counter[id]--;
        scores -= ite->GetScore();
        selected.erase(ite);
    }


    void challenge(Sushi& target) {
        unsigned int id = target.GetId();
        if (counter.find(id) != counter.end()) return;

        for (auto ite = selected.begin() ; ite != selected.end(); ite++) {
            if (counter[ite->GetId()] == 1) continue;
            erase(ite);
            add(target);
            break;
        }
    }

    void reverse() {
        selected.reverse();
    }

    uint64_t GetScore() {
        uint64_t const currentSize = counter.size();
        uint64_t const currentBonus = currentSize * currentSize;
        return currentBonus + scores;
    }

    void show() {

        for (auto ite : selected) {
            ite.show();
        }

    }
};


int main() {
    size_t N, K;
    cin >> N >> K;
    std::list<Sushi> t;
    for (size_t i = 0; i < N; i++) {
        unsigned int id, score;
        cin >> id >> score;
        t.push_back(Sushi(id, score));
    }
    t.sort(inverse);
    SushiSelector selector;
    auto ite = t.begin();

    for (size_t i = 0; i < K; i++) {
        selector.add(*ite);
        ite++;
    }

    selector.reverse();

    uint64_t score = selector.GetScore();
    for (; ite != t.end(); ite++) {
        selector.challenge(*ite);
        uint64_t const temp = selector.GetScore();
        if (score < temp) score = temp;
    }

    cout << score << endl;

    return 0;
}

