bool vis[N];

int gdp(int st){
	if(!vis[st]){
		vis[st] = 1;	
		rep(c,0,2){
			ll lim[2] = {-1,-1};
			lim[c] = a[st] + d[c];
			int cur = st;
			while(cur < n){
				if(cur == n-1)dp[st] = (dp[st] + 1) % MOD;
				else{
					if(a[cur+1] < min(lim[0],lim[1]))break;	
					else if(a[cur+1] >= max(lim[0],lim[1])){
						dp[st] = (dp[st] + gdp(cur+1)) % MOD;
						break;
					}
					else if(a[cur+1] >= lim[0])lim[0] = a[cur+1] + d[0];
					else if(a[cur+1] >= lim[1])lim[1] = a[cur+1] + d[1];
				}
				++cur;
			}
		}
	}
	return dp[st];
}

