using namespace std;

int score(int min, int player, int stones, vector<int> &nums) {
    int op = 1 - player, winner;
    if (min > stones) {
        return op;
    }

    for (int i = 0; i < nums.size(); i++) {
        winner = score(min, op, stones - nums[i], nums);
        if (winner == player) {
            return player;
        }
    }

    return op;
}

void win(vector<int> &arr1, int stones) {
    int mn = INT_MAX;
    for (auto x: arr1) {
        mn = min(mn, x);
    }
    if (score(mn, 1, stones, arr1)) {
        cout<<"First";
    } else {
        cout<<"Second";
    }
}

