int count(vector<int> ls, int x) {
  const int n = ls.size();
  int l = 0;
  int r = n;
  while (l < r) {
    if (l + 1 >= r) break;
    int m = (l + r) / 2;
    if (ls[m] <= x) l = m;
    else r = m;
  }
  if (ls[l] != x) return 0;
  while (ls[l] == x && l >= 0) --l;
  ++l;
  int c = 0;
  while (ls[l] == x && l < n) {
    ++c;
    ++l;
  }
  return c;
}

