int cmpstr(string str1, string str2){
    if(str1 == str2) return 0;
    for(int i = 0; i < min(str1.size(), str2.size()); i ++){
        if(str1[i] > str2[i]) return 1;
        if(str1[i] < str2[i]) return -1;
    }
    return (str1.size() > str2.size()) ? 1 : -1;
}

