    int maxGcd=1;

    for (int i=0; i<n; i++)
    {
        cin >> A[i];
    }

    sort(A.begin(),A.end());

    for (int i=0; i<n; i++)
    {
        int tmpGcd = A[0];
        for (int j=1; j<n; j++)
        {
            if (i==0 && j==1)
            {
                tmpGcd = A[j];
                continue;
            }
            if (j==i)continue;
            tmpGcd = euclidean_gcd(tmpGcd, A[j]);
            if (tmpGcd == 1)break;
        }
        maxGcd = tmpGcd > maxGcd ? tmpGcd : maxGcd;
    }

    cout << maxGcd << endl;

    return 0;
}
