				--n,--k;
			else
				{
					if(x<0)
						lpos[++lcnt]=x;
					else
						rpos[++rcnt]=x;
				}
		}
	if(k<=0)
		{
			printf("0");
			return 0;
		}
	sort(lpos+1,lpos+1+lcnt,cmp);
