			if(rpos[j]<lpos[i])
				sum=2*rpos[j]-lpos[i];
			else
				sum=rpos[i]-2*lpos[j];
			ans=min(ans,sum);
		}
	printf("%d",ans);
	//fclose(stdin);
	//fclose(stdout);
	return 0;
}
