void djkstra(int x, vector<ll> &shortest, vector<vector<PII>> connective)
{
    vector<int> search = {x};
    vector<int> new_search;
    shortest[x] = 0;
    int v, d;
    while (!search.empty())
    {
        for (auto i : search)
        {
            for (auto j : connective[i])
            {
                v = j.first, d = j.second;
                if (shortest[v] > d + shortest[i])
                {
                    shortest[v] = d + shortest[i];
                    new_search.push_back(v);
                }
            }
        }
        search.clear();
        search = new_search;
        new_search.clear();
    }
}

void dfs(int n, vector<ll> shortest, vector<ll> &path, vector<vector<PII>> connective)
{
    int v, d;

    vector<pair<ll, int>> shortest2(n);
    rep(i, n)
    {
        shortest2[i] = make_pair(shortest[i], i);
    }
    sort(allpt(shortest2));
    path[shortest2[0].second] = 1;

    rep(i, n)
    {
        for (auto j : connective[shortest2[i].second])
        {
            v = j.first, d = j.second;
            if (shortest2[i].first + d == shortest[v])
            {
                path[v] += path[shortest2[i].second];
                path[v] %= mod;
            }
        }
    }
}

