//union find tree
//test : DSL_1_A: Disjoint Set: Union Find Tree : AC  : 2015/11/27

struct UnionFind{
    int n;
    vector<int> p;
    vector<int> group_size;
    ll inconvenience;
    UnionFind(int n) : n(n), inconvenience(n * (n - 1) / 2) {
        p.resize(n);
        group_size.resize(n);
        rep(i, n) p[i] = i;
        rep(i, n) group_size[i] =1;
    }
    int root(int x){
        if(p[x] == x) return x;
        else return p[x] = root(p[x]);
    }
    void unite(int x,int y){
        x = root(x);
        y = root(y);
        if(x != y) {
            inconvenience -= group_size[y] * (n - group_size[y]);
            inconvenience -= group_size[x] * (n - group_size[x]);
            inconvenience += group_size[y] * group_size[x];
            p[y] = x;
            group_size[x] += group_size[y];
            group_size[y] = 0;
            inconvenience += group_size[x] * (n - group_size[x]);
        }
    }
    bool query(int x,int y){
        return root(x) == root(y);
    }
};

int main() {
    int N, M; cin >> N >> M;
    vector<int> A(M), B(M);
    rep(i, M) cin >> A[i] >> B[i];

    UnionFind uf(N);

    vector<ll> ans(M);

    for(int i = M - 1; i >= 0; i--) {
        ans[i] = uf.inconvenience;
        uf.unite(A[i] - 1, B[i] - 1);
    }
    cerr << uf.inconvenience << endl;
    rep(i, M) cout << ans[i] << endl;

    return 0;
}
